std::bitset<8> byte_buffer;
std::string current_path;
std::stack<std::pair<std::shared_ptr<Node>, std::string>> node_stack;

root = std::make_shared<Node>(true);  // Root is always an internal node
node_stack.push({root, ""});

while (infile) {
    char byte;
    infile.read(reinterpret_cast<char*>(&byte), sizeof(byte));

    if (!infile) break;

    byte_buffer = std::bitset<8>(byte);
    for (int i = 0; i < 8; ++i) {
        if (byte_buffer.test(i)) {
            if (node_stack.empty()) {
                throw std::runtime_error("Invalid Huffman dictionary format");
            }

            auto [current_node, path] = node_stack.top();
            node_stack.pop();

            // Create left child (0 bit)
            auto left_child = std::make_shared<Node>(false);
            current_node->left = left_child;
            node_stack.push({left_child, path + "0"});

            // Create right child (1 bit)
            auto right_child = std::make_shared<Node>(false);
            current_node->right = right_child;
            node_stack.push({right_child, path + "1"});
        } else {
            if (node_stack.empty()) {
                throw std::runtime_error("Invalid Huffman dictionary format");
            }

            auto [current_node, path] = node_stack.top();
            node_stack.pop();

            // Leaf node found - read character
            char ch;
            infile.read(reinterpret_cast<char*>(&ch), sizeof(ch));
            if (!infile) break;

            current_node->is_leaf = true;
            current_node->character = ch;
            current_node->path = path;
        }
    }
}

